// Фильтруем сообщения: оставляем только те, где упоминается «ChatGPT»
const items = $input.all();
const results = [];

for (const item of items) {
  const msg = item.json.message || {};
  const text = msg.text || msg.caption || '';

  // Проверяем наличие ключевого слова (регистронезависимо)
  if (/chatgpt/i.test(text)) {
    results.push({
      json: {
        messageId: msg.message_id,
        chatId: msg.chat?.id,
        chatTitle: msg.chat?.title || 'Private',
        fromUser: msg.from?.username || msg.from?.first_name || 'Unknown',
        text: text,
        date: new Date(msg.date * 1000).toISOString()
      }
    });
  }
}

return results;

// Парсим JSON-ответ от OpenAI и объединяем с исходными данными
const items = $input.all();
const results = [];

for (const item of items) {
  const original = $('Filter Brand Mentions').first().json;
  const aiResponse = item.json.message?.content || item.json.choices?.[0]?.message?.content || '{}';

  let parsed;
  try {
    // Извлекаем JSON из ответа (на случай, если модель добавила markdown-блок)
    const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
    parsed = JSON.parse(jsonMatch ? jsonMatch[0] : aiResponse);
  } catch (e) {
    parsed = {
      sentiment: 'unknown',
      confidence: 0,
      summary: aiResponse,
      topics: []
    };
  }

  results.push({
    json: {
      date: original.date,
      chatTitle: original.chatTitle,
      fromUser: original.fromUser,
      originalText: original.text,
      sentiment: parsed.sentiment || 'unknown',
      confidence: parsed.confidence || 0,
      summary: parsed.summary || '',
      topics: Array.isArray(parsed.topics) ? parsed.topics.join(', ') : String(parsed.topics || ''),
      messageId: original.messageId,
      chatId: original.chatId
    }
  });
}

return results;
